# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZİN (SAV) VAHYİ AÇIKLAMA GÖREVİ: TEBYİN (2.1 &amp; 2.2)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Tebyin (Açıklama ve Uygulama)</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" fill="#1e3a8a">• Kur\'an\'da özet (mücmel) olarak emredilen</text>\n  <text x="180" y="112" text-anchor="middle" font-size="11" fill="#1e3a8a">ibadet ve hükümlerin nasıl uygulanacağını</text>\n  <text x="180" y="130" text-anchor="middle" font-size="11" fill="#1e3a8a">söz, fiil ve onaylarla (sünnetle) göstermektir.</text>\n  <text x="180" y="156" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Delil (Nahl suresi, 44. ayet):</text>\n  <text x="180" y="176" text-anchor="middle" font-size="11" fill="#1e3a8a">\'İnsanlara indirileni açıkça beyan edesin</text>\n  <text x="180" y="194" text-anchor="middle" font-size="11" fill="#1e3a8a">diye sana bu Kur\'an\'ı (Zikr\'i) indirdik.\'</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Sünnet olmadan Kur\'an tam anlaşılamaz!</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Nebevi Uygulama Örnekleri (İbadetler)</text>\n  <text x="520" y="94" text-anchor="middle" font-size="11" fill="#14532d">• Namaz: Vakitleri, rekât sayıları, kılınışı</text>\n  <text x="520" y="112" text-anchor="middle" font-size="10" font-weight="bold" fill="#166534">(\'Beni nasıl namaz kılarken görüyorsanız öyle kılın.\')</text>\n  <text x="520" y="136" text-anchor="middle" font-size="11" fill="#14532d">• Hac: Tavaf, sa\'y, vakfe ve menâsikin yapılışı</text>\n  <text x="520" y="154" text-anchor="middle" font-size="10" font-weight="bold" fill="#166534">(\'Hac ibadetinizin kurallarını benden öğreniniz.\')</text>\n  <text x="520" y="178" text-anchor="middle" font-size="11" fill="#14532d">• Zekât: Hangi mallardan ne oranda (1/40 vb.)</text>\n  <text x="520" y="196" text-anchor="middle" font-size="11" fill="#14532d">ve hangi nisap miktarıyla verileceği</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">• Oruç: Sahur, iftar ve orucu bozan durumlar</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÜNNETİN ÇEŞİTLERİ VE HÜKÜM KOYMA (TEŞRİ) ROLÜ</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Üç Boyutuyla Sünnet (Nebevi Uygulama)</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">1. Kavlî (Sözlü) Sünnet — Hadisler:</text>\n  <text x="180" y="114" text-anchor="middle" font-size="11" fill="#713f12">Peygamberimizin mübarek sözleri ve öğütleri.</text>\n  <text x="180" y="140" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">2. Fiilî (Uygulamalı) Sünnet:</text>\n  <text x="180" y="158" text-anchor="middle" font-size="11" fill="#713f12">İbadetleri ve ahlakı bizzat yaşayarak göstermesi.</text>\n  <text x="180" y="184" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">3. Takrîrî (Onaylayıcı) Sünnet:</text>\n  <text x="180" y="202" text-anchor="middle" font-size="11" fill="#713f12">Sahabilerin yaptığı güzel işleri görüp onaylaması</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" fill="#713f12">(sessiz kalarak veya överek uygun bulması).</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Teşri (Hüküm Koyma) Görevi</text>\n  <text x="520" y="94" text-anchor="middle" font-size="11" fill="#581c87">• Kur\'an\'da açıkça detayı bulunmayan konularda</text>\n  <text x="520" y="112" text-anchor="middle" font-size="11" fill="#581c87">Hz. Peygamber\'in dinî hüküm belirlemesidir.</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Delil (A\'râf, 157 &amp; Haşr, 7):</text>\n  <text x="520" y="156" text-anchor="middle" font-size="11" fill="#581c87">\'Peygamber temiz şeyleri helal, pis şeyleri haram</text>\n  <text x="520" y="174" text-anchor="middle" font-size="11" fill="#581c87">kılar.\' · \'Peygamber size ne verdiyse onu alın...\'</text>\n  <text x="520" y="200" text-anchor="middle" font-size="11" fill="#581c87">Örnek: Ehlî eşek etinin ve yırtıcı hayvanların</text>\n  <text x="520" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">haram kılınması, fıtır sadakası (fitre) hükmü.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZE İTAAT VE TEMSİL / TEZKİYE ÖRNEKLİĞİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Resulullah\'a İtaat = Allah\'a İtaat</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">Nisâ Suresi, 80. Ayet:</text>\n  <text x="180" y="114" text-anchor="middle" font-size="11" fill="#881337">\'Kim Peygamber\'e itaat ederse, gerçekte</text>\n  <text x="180" y="132" text-anchor="middle" font-size="11" fill="#881337">Allah\'a itaat etmiş olur.\'</text>\n  <text x="180" y="160" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">Âl-i İmrân Suresi, 31. Ayet:</text>\n  <text x="180" y="178" text-anchor="middle" font-size="11" fill="#881337">\'De ki: Eğer Allah\'ı seviyorsanız bana uyun ki</text>\n  <text x="180" y="196" text-anchor="middle" font-size="11" fill="#881337">Allah da sizi sevsin ve günahlarınızı bağışlasın.\'</text>\n  <text x="180" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">Sünnete uymak Allah sevgisinin ölçüsüdür.</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Yaşayan Kur\'an: Temsil ve Tezkiye</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">Üsve-i Hasene (Ahzâb, 21):</text>\n  <text x="520" y="114" text-anchor="middle" font-size="11" fill="#164e63">Müminler için \'en güzel örnek\' olmasıdır.</text>\n  <text x="520" y="142" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">Hz. Âişe\'nin (ra) Tanımı:</text>\n  <text x="520" y="160" text-anchor="middle" font-size="11" fill="#164e63">\'Onun ahlakı Kur\'an\'dı.\' (Temsil görevi)</text>\n  <text x="520" y="188" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">Tezkiye (Arındırma — Cuma, 2):</text>\n  <text x="520" y="206" text-anchor="middle" font-size="11" fill="#164e63">Kalpleri şirkten ve kötü huylardan temizleyip</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" fill="#164e63">kitap ve hikmeti (sünneti) öğretmesidir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
